 s=src[i];rows.append({'id':i,'activation':'Action','rangeFeet':range_ft,'targets':targets,'duration':duration,'concentration':conc,'components':['V','S','F'],'resolution':resolution,'effect':effect,'scaling':'None. No automatic increase in damage, range, targets, duration, uses or magnitude.','limitations':limits+common,'designNotes':notes,'implementationStatus':'LOCAL CANDIDATE — source-reconciled; exact review pending; not selectable','sourcePlacements':s['sourcePlacements'],'sourceCoreEntries':s['sourceCoreEntries'],'classAccessEvidence':s['classAccess'],'sourceReview':[review,clarification]+([eligibility] if i=='arcane-shield-shatter' else []),'reviewEvidence':[]})

