# Improve rendered prose spacing only; never transform IDs, exact source blocks or class evidence.
import re
def prose(t):
 t=re.sub(r'(?i)\b(within|one|shared|among|toward|before|after|every|base|rank|natural|DC|missiles)(?=\d)',r'\1 ',t)
 t=re.sub(r'(\d+)(feet|foot|seconds|HP|RP)\b',r'\1 \2',t)
 t=re.sub(r'(\d+d\d+(?:\+\d+)?)(fire|cold|thunder|force|lightning|bludgeoning|piercing|poison|necrotic)\b',r'\1 \2',t)
 t=re.sub(r'(?<=\d),(?=\S)',', ',t)
 return t
